import six
import abc
import re
from ta_moler.cmd.shared.nokiaunix.generic_nokia_unix import GenericNokiaUnix

__author__ = 'Marcin Usielski'
__copyright__ = 'Copyright (C) 2020, Nokia'
__email__ = 'marcin.usielski@nokia.com'


@six.add_metaclass(abc.ABCMeta)
class GenericIfOutput(GenericNokiaUnix):
    """Generic for commands that can required output or not."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Init generic for commands that can required output or not.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenericIfOutput, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self._re_no_output_options = re.compile(r"reset", re.IGNORECASE)  # Where this regex is found in command string
        # it means no parsed output is required. If not found then parsed output is required.
        self._checked_if_ret_required = False

    def on_new_line(self, line, is_full_line):
        """
        Parse command output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        self._set_if_ret_required()
        return super(GenericIfOutput, self).on_new_line(line, is_full_line)

    def _set_if_ret_required(self):
        """
        Set ret_required flag to True based on command options.

        :return: None
        """
        if self._checked_if_ret_required is False:
            self._checked_if_ret_required = True
            if self._regex_helper.search_compiled(self._re_no_output_options, self.command_string):
                self.ret_required = False
            else:
                self.ret_required = True
